-- 📚 꼭집 주거 사전 — 50년 공공임대 — 분양전환 없음 · 2년 단위 갱신 · 소득·자산 한도 칸 비어 있음 · 2026
-- 재계산 SQL(관리 API에서 그대로 실행 · 읽기만). 범위: 공고일 2026년 · 유형 표준값 「공공임대(6·10·50년)」 중 제목에 50년(공임50) · 정책 행이 있는(분석된) 공고만.
-- 확인 2026-10-14 · 결과 요지: titled 54 · analyzed 11 · noconv 10 · renew2 11 · elig_rows 11 · elig_limits_null 11 · elig_exempt_true 0
with a as(select distinct on(x.announcement_id)x.announcement_id,x.title,coalesce(m.std_type,x.housing_type)std,extract(year from coalesce(x.announcement_date,x.created_at::date))::int yr from announcements x left join housing_type_map m on m.source_table='announcements' and m.source=x.source and m.housing_type=x.housing_type order by x.announcement_id,(x.source='LH')desc,x.created_at desc),f as(select announcement_id from a where yr=2026 and std='공공임대(6·10·50년)' and title~'50\s*년|공임50'),y as(select p.announcement_id,regexp_replace(p.content_raw,'\s+',' ','g')t from announcement_policies p join f using(announcement_id)),e as(select c.* from eligibility_criteria c join f using(announcement_id))select json_build_object('titled',(select count(*) from f),'analyzed',(select count(distinct announcement_id) from y),'noconv',(select count(distinct announcement_id) from y where t~'분양\s*전환\s*(되지|하지)\s*않|분양전환\s*(이\s*)?(불가|없)'),'noconv_ex',(select json_agg(i) from(select distinct announcement_id i from y where t~'분양\s*전환\s*(되지|하지)\s*않' order by 1 desc limit 3)q),'renew2',(select count(distinct announcement_id) from y where t~'2\s*년\s*(단위|마다)'),'elig_rows',(select count(*) from e),'elig_limits_null',(select count(*) from e where income_pct is null and asset_limit is null and car_limit is null),'elig_exempt_true',(select count(*) from e where income_limit_exempt or asset_limit_exempt))j;
